div.script:
(function () {
    var drop = document.getElementById('dl_drop');
    var input = document.getElementById('dl_files');
    var list = document.getElementById('dl_pick_list');
    var summary = document.getElementById('dl_pick_summary');
    var notice = document.getElementById('dl_pick_notice');
    var clearBtn = document.getElementById('dl_pick_clear');
    var hint = document.getElementById('dl_drop_hint');
    if (!drop || !input || !list || !summary || !notice || !clearBtn || !hint) { return; }
    var HINT_DEFAULT = hint.textContent;
    var picked = [];      // 待上传集合：拖拽与文件选择框两条入口共用这一份
    var dupNotice = '';   // 重复文件提示（去重但不静默）
    var syncWarn = '';    // 无法重建 FileList 时的兜底告警

    function short(v) {
        return v >= 10 ? String(Math.round(v)) : v.toFixed(1);
    }

    function humanSize(n) {
        if (typeof n !== 'number' || isNaN(n) || !(n >= 0)) { return '大小未知'; }
        if (n >= 1073741824) { return short(n / 1073741824) + ' GB'; }
        if (n >= 1048576) { return short(n / 1048576) + ' MB'; }
        if (n >= 1024) { return short(n / 1024) + ' KB'; }
        return n + ' B';
    }

    function keyOf(file) {
        // 去重口径：文件名 + 大小
        return JSON.stringify([file.name, file.size]);
    }

    function syncInput() {
        // 把待上传集合写回 input.files：服务端收到的集合必须与界面清单一致
        try {
            var dt = new DataTransfer();
            picked.forEach(function (it) { dt.items.add(it.file); });
            input.files = dt.files;
            syncWarn = '';
        } catch (err) {
            syncWarn = '提示：当前浏览器无法同步待上传清单，文件选择框里的内容可能与清单不一致，请刷新页面后重试。';
            if (window.console && window.console.error) {
                window.console.error('edu_downloads_upload_panel: 重建 input.files 失败', err);
            }
        }
    }

    function render() {
        list.textContent = '';
        var total = 0;
        picked.forEach(function (it, idx) {
            total += it.file.size || 0;
            var li = document.createElement('li');
            li.className = 'd-flex justify-content-between align-items-center gap-2 border-top py-1';
            var meta = document.createElement('span');
            meta.className = 'small text-break';
            var seq = document.createElement('span');
            seq.className = 'text-muted me-1';
            seq.textContent = String(idx + 1) + '.';
            var nm = document.createElement('span');
            nm.className = 'fw-semibold';
            nm.textContent = it.file.name;
            var sz = document.createElement('span');
            sz.className = 'text-muted ms-1';
            sz.textContent = humanSize(it.file.size);
            meta.appendChild(seq);
            meta.appendChild(nm);
            meta.appendChild(sz);
            var rm = document.createElement('button');
            rm.type = 'button';
            rm.className = 'btn btn-sm btn-outline-danger py-0 flex-shrink-0';
            rm.setAttribute('aria-label', '移除 ' + it.file.name);
            rm.textContent = '移除';
            rm.addEventListener('click', function () { removeAt(idx); });
            li.appendChild(meta);
            li.appendChild(rm);
            list.appendChild(li);
        });
        if (picked.length) {
            summary.textContent = '已选 ' + picked.length + ' 个文件 · 合计 ' + humanSize(total);
            hint.textContent = '已选 ' + picked.length + ' 个文件：可继续拖入，或用下方按钮继续选择';
        } else {
            summary.textContent = '尚未选择任何文件';
            hint.textContent = HINT_DEFAULT;
        }
        clearBtn.disabled = !picked.length;
        var msg = syncWarn || dupNotice;
        notice.textContent = msg;
        if (msg) {
            notice.classList.remove('d-none');
        } else {
            notice.classList.add('d-none');
        }
    }

    function addFiles(fileList) {
        var added = 0;
        var dups = [];
        Array.prototype.slice.call(fileList).forEach(function (file) {
            var k = keyOf(file);
            var dup = picked.some(function (it) { return it.key === k; });
            if (dup) { dups.push(file.name); return; }
            picked.push({ file: file, key: k });
            added += 1;
        });
        if (dups.length) {
            dupNotice = '提示：已忽略 ' + dups.length + ' 个重复文件（文件名与大小都相同）：'
                + dups.slice(0, 3).join('、') + (dups.length >= 4 ? ' 等' : '')
                + '。如需上传，请先改文件名或另存一份。';
        } else if (added) {
            dupNotice = '';
        }
        syncInput();
        render();
        return added;
    }

    function removeAt(idx) {
        picked.splice(idx, 1);
        dupNotice = '';
        syncInput();
        render();
        var btns = list.querySelectorAll('button');
        if (btns.length) {
            btns[Math.min(idx, btns.length - 1)].focus();
        } else {
            input.focus();
        }
    }

    ['dragenter', 'dragover'].forEach(function (ev) {
        drop.addEventListener(ev, function (e) {
            e.preventDefault();
            drop.classList.add('border-primary', 'bg-white', 'text-primary');
        });
    });
    drop.addEventListener('dragleave', function (e) {
        e.preventDefault();
        drop.classList.remove('border-primary', 'bg-white', 'text-primary');
    });
    drop.addEventListener('drop', function (e) {
        e.preventDefault();
        drop.classList.remove('border-primary', 'bg-white', 'text-primary');
        var files = e.dataTransfer ? e.dataTransfer.files : null;
        if (files && files.length) {
            addFiles(files);   // 追加，不覆盖
        } else {
            dupNotice = '提示：这次拖入没有识别到文件，请从文件管理器里拖入文件，或用下方按钮选择。';
            render();
        }
    });
    input.addEventListener('change', function () {
        if (input.files && input.files.length) {
            addFiles(input.files);
        }
    });
    clearBtn.addEventListener('click', function () {
        if (!picked.length) { return; }
        picked = [];
        dupNotice = '';
        syncInput();
        render();
        input.focus();
    });
    if (input.form) {
        input.form.addEventListener('submit', function () {
            syncInput();
            render();
        });
    }
    render();
})();

t.script:
(function () {
    var all = document.getElementById('dl_check_all');
    var cnt = document.getElementById('dl_sel_count');
    function refresh() {
        var n = document.querySelectorAll('.dl-row-check:checked').length;
        if (cnt) { cnt.textContent = n; }
    }
    if (all) {
        all.addEventListener('change', function () {
            document.querySelectorAll('.dl-row-check').forEach(function (cb) {
                cb.checked = all.checked;
            });
            refresh();
        });
    }
    document.querySelectorAll('.dl-row-check').forEach(function (cb) {
        cb.addEventListener('change', refresh);
    });
    document.querySelectorAll('form.dl-confirm').forEach(function (f) {
        f.addEventListener('submit', function (ev) {
            if (!window.confirm(f.getAttribute('data-confirm') || '确认？')) {
                ev.preventDefault();
            }
        });
    });
})();
